 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator row or column, then compare corresponding
    # cells in the two equally sized panels. Their sole shared color is the
    # panel background; matching cells of that color are marked with 3.
    separators = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            separators.append(("row", r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            separators.append(("col", c))

    for axis, pos in separators:
        if axis == "row":
            first, second = grid[:pos], grid[pos + 1:]
            if not first or len(first) != len(second):
                continue
        else:
            first = [row[:pos] for row in grid]
            second = [row[pos + 1:] for row in grid]
            if not first[0] or len(first[0]) != len(second[0]):
                continue

        shared = set(v for row in first for v in row) & set(v for row in second for v in row)
        if len(shared) != 1:
            continue
        background = next(iter(shared))
        return [[3 if a == background and b == background else background
                 for a, b in zip(row_a, row_b)]
                for row_a, row_b in zip(first, second)]

    raise ValueError("no separator yielding equal panels with one shared color")


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
